public class Main {
    public static void main(String[] args) {
        int age = Integer.parseInt(args[0]);
        boolean hasConsent = args[1].equals("yes");
        System.out.println(registrationMessage(age, hasConsent));
    }

    static String registrationMessage(int age, boolean hasConsent) {
        if (age >= 0) {
            if (age < 18) {
                if (hasConsent) {
                    return "登録できます";
                } else {
                    return "同意が必要";
                }
            } else {
                return "登録できます";
            }
        } else {
            return "入力エラー";
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int unitPriceYen = Integer.parseInt(args[0]);
        int quantity = Integer.parseInt(args[1]);
        int subtotalYen = unitPriceYen * quantity;
        // 商品代金が3000円を超えたら送料無料。
        int shippingFeeYen = subtotalYen >= 3000 ? 0 : 500;
        int totalYen = subtotalYen + shippingFeeYen;
        // 文字列を表示する。
        System.out.println("商品代金: " + subtotalYen + "円 / 送料: " + shippingFeeYen + "円 / 合計: " + totalYen + "円");
    }
}

public class Main {
    public static void main(String[] args) {
        ShopManager manager = new ShopManager(args[0], Integer.parseInt(args[1]), Integer.parseInt(args[2]));
        manager.printReceipt();
    }
}

class ShopManager {
    String productName;
    int unitPriceYen;
    int quantity;

    ShopManager(String productName, int unitPriceYen, int quantity) {
        this.productName = productName;
        this.unitPriceYen = unitPriceYen;
        this.quantity = quantity;
    }

    void printReceipt() {
        int subtotalYen = unitPriceYen * quantity;
        String text = productName + " x " + quantity + " = " + subtotalYen + "円";
        System.out.println(text);
    }
}

public class Main {
    public static void main(String[] args) {
        Address address = new Address(args[0]);
        Profile profile = new Profile(address);
        User user = new User(profile);
        System.out.println("配送先: " + user.getProfile().getAddress().getCity());
    }
}

class User {
    private final Profile profile;
    User(Profile profile) { this.profile = profile; }
    Profile getProfile() { return profile; }
}

class Profile {
    private final Address address;
    Profile(Address address) { this.address = address; }
    Address getAddress() { return address; }
}

class Address {
    private final String city;
    Address(String city) { this.city = city; }
    String getCity() { return city; }
}
